import{f as e,g as t,l as n,n as r,p as i,s as a}from"./index-C58jEfpN.js";import{t as o}from"./navigate-Bgx1iBYm.js";var s={name:`InterviewEnglishPage`,methods:{goHome(){o(`/`)},navigate(e){o(e)}}},c={class:`subpage`},l={class:`subpage-container`},u={class:`subpage-topbar`},d={class:`subpage-topbar-right`};function f(r,o,s,f,p,m){return t(),e(`div`,c,[n(`div`,l,[n(`header`,u,[o[2]||=n(`div`,{class:`subpage-topbar-left`},[n(`span`,{class:`icon`},`🇬🇧`),n(`div`,null,[n(`h1`,null,`English Interview Preparation`),n(`div`,{class:`subtitle`},`30-day lộ trình luyện tiếng Anh phỏng vấn Java Backend`)])],-1),n(`div`,d,[n(`a`,{class:`subpage-back`,href:`#`,onClick:o[0]||=a((...e)=>m.goHome&&m.goHome(...e),[`prevent`])},`← Trang chủ`),n(`a`,{class:`subpage-back`,href:`#`,onClick:o[1]||=a(e=>m.navigate(`/interview`),[`prevent`])},`☕ Java Interview`)])]),o[3]||=i(`<p class="page-desc" data-v-61ed1e8a>30-day lộ trình luyện tiếng Anh phỏng vấn Java Backend — mỗi ngày 30-45 phút. Kết hợp kỹ thuật + English.</p><div class="week-card" data-v-61ed1e8a><h2 data-v-61ed1e8a>📅 Week 1: Java Core &amp; OOP</h2><div class="day-list" data-v-61ed1e8a><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 1</strong>Introduce Yourself + OOP concepts</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 2</strong>Encapsulation, Inheritance, Polymorphism</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 3</strong>Abstract Class vs Interface</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 4</strong>Collection Framework vocabulary</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 5</strong>HashMap &amp; equals/hashCode</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 6</strong>Exception Handling in English</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 7</strong>Review + Mock interview (Java Core)</div></div><h3 data-v-61ed1e8a>🎯 Key Vocabulary</h3><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: Can you explain OOP principles?</div><div class="a" data-v-61ed1e8a>&quot;Object-Oriented Programming has four main principles. First, Encapsulation means hiding internal data and only exposing public methods. Second, Inheritance allows a class to reuse fields and methods from a parent class. Third, Polymorphism enables a single method to behave differently based on the object. Fourth, Abstraction hides implementation details and shows only essential features.&quot;</div></div><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: What is the difference between an Interface and an Abstract Class?</div><div class="a" data-v-61ed1e8a>&quot;An interface defines a contract — it only declares methods (and default methods since Java 8). A class can implement multiple interfaces. An abstract class can have both abstract and concrete methods, can hold state with fields, and a class can only extend one abstract class. Use interfaces for defining behavior, abstract classes for sharing common code.&quot;</div></div></div><div class="week-card" data-v-61ed1e8a><h2 data-v-61ed1e8a>📅 Week 2: Spring Boot &amp; Database</h2><div class="day-list" data-v-61ed1e8a><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 8</strong>Spring Boot, IoC, DI explained</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 9</strong>REST API design in English</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 10</strong>JPA &amp; Hibernate relationships</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 11</strong>SQL, JOIN, Index in English</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 12</strong>Transaction &amp; ACID properties</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 13</strong>Security, JWT, Authentication</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 14</strong>Review + Mock interview (Spring)</div></div><h3 data-v-61ed1e8a>🎯 Key Vocabulary</h3><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: What is Dependency Injection?</div><div class="a" data-v-61ed1e8a>&quot;Dependency Injection is a design pattern where dependencies are provided to an object rather than the object creating them itself. The Spring IoC container manages this. Constructor injection is the recommended approach because it makes dependencies explicit, enables immutability, and simplifies testing. Instead of using &#39;new&#39; keyword, we let the framework inject the required beans.&quot;</div></div><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: Can you explain the difference between PUT and PATCH?</div><div class="a" data-v-61ed1e8a>&quot;PUT is used to update an entire resource — you send the full object. PATCH is for partial updates — you only send the fields you want to change. PUT is idempotent, meaning calling it multiple times produces the same result. PATCH is generally not idempotent. For example, if a user has 10 fields, PUT requires all 10, but PATCH only needs the fields that changed.&quot;</div></div></div><div class="week-card" data-v-61ed1e8a><h2 data-v-61ed1e8a>📅 Week 3: Advanced Topics</h2><div class="day-list" data-v-61ed1e8a><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 15</strong>Microservices &amp; Kafka explained</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 16</strong>Docker &amp; CI/CD vocabulary</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 17</strong>Cloud (AWS) basics in English</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 18</strong>System Design: URL Shortener</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 19</strong>N+1 problem &amp; optimization</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 20</strong>Design Patterns (Singleton, Strategy)</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 21</strong>Review + Mock interview (System Design)</div></div><h3 data-v-61ed1e8a>🎯 Key Vocabulary</h3><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: What is the N+1 problem in Hibernate?</div><div class="a" data-v-61ed1e8a>&quot;The N+1 problem occurs when you fetch a list of N parent entities and each one triggers an additional query for its associated children. So you end up with 1 query for the parents plus N queries for the children. We can solve it using JOIN FETCH in JPQL, which loads everything in a single query. Another approach is enabling batch fetching or using DTO projections.&quot;</div></div><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: How do microservices communicate?</div><div class="a" data-v-61ed1e8a>&quot;There are two main patterns: synchronous and asynchronous. For synchronous communication, services use REST or gRPC. For asynchronous, they use message brokers like Kafka or RabbitMQ. I prefer async communication for decoupling — for example, when an order is created, the order service emits an event to Kafka, and other services consume it independently.&quot;</div></div></div><div class="week-card" data-v-61ed1e8a><h2 data-v-61ed1e8a>📅 Week 4: Mock Interview &amp; Polish</h2><div class="day-list" data-v-61ed1e8a><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 22</strong>Behavioral questions (STAR method)</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 23</strong>Project presentation in English</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 24</strong>Common coding questions (English)</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 25</strong>Full mock interview Round 1</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 26</strong>Weak areas review</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 27</strong>Full mock interview Round 2</div><div class="day-item" data-v-61ed1e8a><strong data-v-61ed1e8a>Day 28-30</strong>Final review + Confidence building</div></div><h3 data-v-61ed1e8a>🎯 Key Vocabulary</h3><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: Tell me about a challenging project you worked on.</div><div class="a" data-v-61ed1e8a>&quot;In my recent project, I built an order management system using Spring Boot and microservices. The biggest challenge was handling the N+1 query problem and ensuring data consistency across services. I solved the N+1 problem by using JOIN FETCH and batch fetching. For consistency, I implemented the Saga pattern with Kafka for event-driven communication. The result was a scalable system that handles thousands of orders per day.&quot;</div></div><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: What are your strengths and weaknesses?</div><div class="a" data-v-61ed1e8a>&quot;My main strength is my strong foundation in Java and Spring Boot. I write clean, testable code with proper exception handling and validation. I&#39;m also good at debugging — I can analyze logs, use profilers, and optimize performance. My weakness is that I sometimes spend too much time on code perfection. I&#39;m learning to balance quality with delivery speed by focusing on critical paths first.&quot;</div></div></div><div class="week-card" data-v-61ed1e8a><h2 data-v-61ed1e8a>📊 English Skills Assessment</h2><div class="skill-grid" data-v-61ed1e8a><div class="skill-card" data-v-61ed1e8a><h5 data-v-61ed1e8a>🗣️ Speaking</h5><p data-v-61ed1e8a>Luyện nói technical terms, describe architecture, answer behavioral questions. Ghi âm và nghe lại.</p></div><div class="skill-card" data-v-61ed1e8a><h5 data-v-61ed1e8a>👂 Listening</h5><p data-v-61ed1e8a>Xem tech talks (Spring Tips, Java Brains), podcast (Java Pub House). Note key terms.</p></div><div class="skill-card" data-v-61ed1e8a><h5 data-v-61ed1e8a>📖 Reading</h5><p data-v-61ed1e8a>Đọc technical documentation (Spring docs, Baeldung), blog posts. Focus on sentence structure.</p></div><div class="skill-card" data-v-61ed1e8a><h5 data-v-61ed1e8a>✍️ Writing</h5><p data-v-61ed1e8a>Viết technical answers, code comments, commit messages bằng tiếng Anh. Review grammar.</p></div></div><h3 data-v-61ed1e8a>📝 Common Interview Questions — English Version</h3><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: Why did you choose Java?</div><div class="a" data-v-61ed1e8a>&quot;I chose Java because of its strong ecosystem, platform independence through the JVM, and excellent tooling. Java has a vast community, reliable frameworks like Spring Boot, and is widely used in enterprise environments. The combination of performance, scalability, and backward compatibility makes it a solid choice for building production-grade applications.&quot;</div></div><div class="qa-block" data-v-61ed1e8a><div class="q" data-v-61ed1e8a>Q: Where do you see yourself in 5 years?</div><div class="a" data-v-61ed1e8a>&quot;In 5 years, I see myself as a senior backend engineer with deep expertise in distributed systems and cloud architecture. I want to mentor junior developers, contribute to system design decisions, and lead technical projects. I&#39;m also interested in learning more about event-driven architecture and Kubernetes.&quot;</div></div></div><div class="week-card" data-v-61ed1e8a><h2 data-v-61ed1e8a>📚 Resources</h2><p data-v-61ed1e8a><strong data-v-61ed1e8a>Books:</strong> &quot;Effective Java&quot; (Joshua Bloch), &quot;Spring in Action&quot;</p><p data-v-61ed1e8a><strong data-v-61ed1e8a>Websites:</strong> Baeldung, Medium, LeetCode (solving + explaining in English)</p><p data-v-61ed1e8a><strong data-v-61ed1e8a>YouTube:</strong> Java Brains, Spring Tips, Amigoscode</p><p data-v-61ed1e8a><strong data-v-61ed1e8a>Practice:</strong> Record yourself answering, join English tech communities, find a speaking partner</p><hr data-v-61ed1e8a><p class="resources-note" data-v-61ed1e8a>📌 Tài liệu tham khảo từ: <code data-v-61ed1e8a>30_day_english_plan_java_interview.pdf</code> và <code data-v-61ed1e8a>English_Skill.docx</code></p></div>`,7)])])}var p=r(s,[[`render`,f],[`__scopeId`,`data-v-61ed1e8a`]]);export{p as default};